package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamAthleticsBank1 {
    private const val T = "මලල ක්‍රීඩා ඉසව්, ශිල්පීය ක්‍රම හා නීති රීති"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ලෝක මලල ක්‍රීඩා සංගමයේ (World Athletics) සම්මත ප්‍රමිතියට අනුව ධාවන පථයක එක් සම්පූර්ණ වටයක දිග මීටර් කීයද?", "මීටර් 400කි", "මීටර් 200කි", "මීටර් 500කි", "මීටර් 300කි", "සම්මත මලල ක්‍රීඩා ධාවන පථයක ඇතුළත්ම මංතීරුවේ (මංතීරු 1) එක් වටයක නිල දිග මීටර් 400කි."),
        q("සම්මත මලල ක්‍රීඩා ධාවන පථයක එක් මංතීරුවක (Lane) නියමිත පළල පරාසය කුමක්ද?", "මීටර් 1.22 සිට 1.25 දක්වා", "මීටර් 2.00 සිට 2.50 දක්වා", "මීටර් 0.80 සිට 1.00 දක්වා", "මීටර් 1.50 සිට 1.80 දක්වා", "World Athletics නීතිරීති අනුව එක් ධාවන මංතීරුවක පළල මීටර් 1.22ක් (සෙන්ටිමීටර 5ක රේඛාවද ඇතුළුව) විය යුතුය."),
        q("මලල ක්‍රීඩාවේ කෙටි දුර ධාවන (Sprint) ඉසව් සඳහා අයත් වන සම්මත ධාවන ඉසව් ත්‍රිත්වය කුමක්ද?", "මීටර් 100, මීටර් 200 සහ මීටර් 400", "මීටර් 800, මීටර් 1500 සහ මීටර් 5000", "මීටර් 100, මීටර් 800 සහ මැරතන්", "මීටර් 200, මීටර් 400 සහ මීටර් 1500", "මීටර් 400 හෝ ඊට අඩු තනි ධාවන ඉසව් කෙටි දුර ධාවන ඉසව් ලෙස සැලකේ."),
        q("මීටර් 100, 200 සහ 400 කෙටි දුර ධාවන ඉසව් ආරම්භ කිරීම සඳහා අනිවාර්යයෙන් භාවිත කළ යුතු උපකරණය කුමක්ද?", "ආරම්භක කුට්ටි (Starting Blocks)", "ස්ටොප් වොච්", "කඩුලු", "යෂ්ටිය", "ජාත්‍යන්තර හා ජාතික මට්ටමේ සියලුම කෙටි දුර ධාවන ඉසව් සඳහා ආරම්භක කුට්ටි භාවිතය අනිවාර්ය නීතියකි."),
        q("කෙටි දුර ධාවන ආරම්භයේදී භාවිත කරන නිවැරදි ආරම්භක ඉරියව් වර්ගය කුමක්ද?", "නැමී ආරම්භය (Crouch Start)", "සිටගෙන ආරම්භය", "වාඩිවී ආරම්භය", "පැන ආරම්භය", "ආරම්භක කුට්ටි මත දණගසා නැමී ආරම්භ කිරීම (Crouch start) මගින් උපරිම ඉදිරි තෙරපුමක් ලැබේ."),
        q("කෙටි දුර ධාවන ඉසව්වකදී ආරම්භක විනිසුරු (Starter) විසින් ලබාදෙන සම්මත විධාන අනුපිළිවෙළ කුමක්ද?", "'ඔබගේ ස්ථාන කරා' (On your marks) — 'සූදානම්' (Set) — ආරම්භක වෙඩි හඬ", "'සූදානම්' — 'දුවන්න' — වෙඩි හඬ", "'ඔබගේ ස්ථාන කරා' — 'දුවන්න'", "'එක, දෙක, තුන' — වෙඩි හඬ", "නැමී ආරම්භය සහිත සියලු ඉසව්වලට විධාන දෙකක් සහ වෙඩි හඬ නිකුත් කෙරේ."),
        q("නැමී ආරම්භයේදී 'ඔබගේ ස්ථාන කරා' (On your marks) විධානයට ක්‍රීඩකයා ගත යුතු නිවැරදි ඉරියව්ව කුමක්ද?", "දෑත් උරහිස් පළලට තබා ආරම්භක රේඛාවට පිටුපසින් තැබීම සහ පසුපස දණහිස බිම ස්පර්ශ කර තැබීම", "ආරම්භක රේඛාව මත අත් තැබීම", "දෙපයින් කෙළින් සිටගෙන සිටීම", "ඉදිරියට දිව යාම", "අත්ල ආරම්භක රේඛාව ස්පර්ශ නොකළ යුතු අතර රේඛාවට පිටුපසින් සම්පූර්ණයෙන්ම ස්ථානගත විය යුතුය."),
        q("නැමී ආරම්භයේදී 'සූදානම්' (Set) විධානය ලැබුණු විගස ක්‍රීඩකයා කළ යුත්තේ කුමක්ද?", "උකුල උරහිස් මට්ටමට වඩා මඳක් ඉහළට ඔසවා ගුරුත්ව කේන්ද්‍රය ඉදිරියට ගෙන විවේකීව නිශ්චල වීම", "වහාම ඉදිරියට දිව යාම", "ආපසු නැගිටීම", "පසුපසට පියවර තැබීම", "Set ඉරියව්වේදී සිරුරේ බර දෑත් සහ පාද අතර සමබරව බෙදී ගොස් ක්ෂණික පිපුරුම් තල්ලුවකට සූදානම් වේ."),
        q("ක්‍රීඩකයෙකුගේ උස සහ පාදවල දිග අනුව ආරම්භක කුට්ටි දෙක අතර පරතරය වෙනස් වන නැමී ආරම්භක විලාස 3 මොනවාද?", "උණ්ඩ ආරම්භය (Bullet), මධ්‍යම ආරම්භය (Medium) සහ දිගු ආරම්භය (Elongated)", "ඉහළ, මැද සහ පහළ ආරම්භය", "වේගවත්, මධ්‍යම සහ මන්දගාමී ආරම්භය", "තනි, ද්විත්ව සහ ත්‍රිත්ව ආරම්භය", "පාද අතර පරතරය අනුව ක්‍රීඩකයාගේ පහසුවට ගැලපෙන ආරම්භක විලාසය තෝරාගනී."),
        q("මලල ක්‍රීඩා නීති රීති අනුව 'බොරු ආරම්භයක්' (False Start) සිදුකළ ක්‍රීඩකයෙකුට ලබාදෙන ක්ෂණික දඬුවම කුමක්ද?", "පළමු වරදේදීම අදාළ තරගයෙන් නුසුදුස්සෙකු (DQ) කර ඉවත් කිරීම", "කහ කාඩ්පතක් පෙන්වා අනතුරු ඇඟවීම", "ලකුණු 5ක් අඩු කිරීම", "මීටර් 5ක් පසුපසින් දිවීමට සැලැස්වීම", "2010 වසරේ සිට ක්‍රියාත්මක World Athletics නීතිය අනුව පළමු බොරු ආරම්භය කළ ක්‍රීඩකයා වහාම තරගයෙන් ඉවත් කෙරේ."),
        q("කෙටි දුර ධාවනයකදී උපරිම වේගයට ළඟාවීම සඳහා ශරීරය මඳක් ඉදිරියට නැඹුරු කර කෙටි පියවරවලින් ආරම්භ වන අදියර කුමක්ද?", "ත්වරණ අදියර (Acceleration Phase)", "උපරිම වේග අදියර", "වේගය පිරිහීමේ අදියර", "නිමාවීමේ අදියර", "මුල් මීටර් 30-40 තුළ ශරීරය ක්‍රමයෙන් කෙළින් කරමින් පියවර දිග හා සීඝ්‍රතාව වැඩි කිරීම ත්වරණයයි."),
        q("කෙටි දුර ධාවන ඉසව්වක නිමාව (Finish) විනිශ්චය කරනු ලබන්නේ ක්‍රීඩකයාගේ ශරීරයේ කුමන කොටස නිමා රේඛාව පසුකළ මොහොතෙන්ද?", "උඩුකය හෙවත් කඳ කොටස (Torso)", "හිස හෝ මුහුණ", "ඉදිරියට දිගු කළ අත", "පෙරමුණ ගත් පාදය", "අත්, පාද, බෙල්ල හෝ හිස නොව උඩුකය (Torso) නිමාවන රේඛාවේ සිරස් තලය පසු කරන මොහොත නිල නිමාව වේ."),
        q("ධාවන ඉසව්වක නිමාවේදී යොදාගන්නා ප්‍රධාන නිමා ශිල්පීය ක්‍රම දෙක මොනවාද?", "ළය ඉදිරියට තල්ලු කිරීම (Chest Thrust) සහ උරහිස ඇල කිරීම (Shoulder Shrug)", "පැන නිමාවීම සහ බිම පෙරළීම", "අත් දිගු කිරීම සහ නැවතීම", "පසුපසට හැරීම සහ නැවතීම", "තීරණාත්මක තත්පරයෙන් සියයෙන් පංගුවක ජයක් සඳහා ළය හෝ උරහිස ඉදිරියට තල්ලු කර නිමාව ලබාගනී."),
        q("මධ්‍යම දුර ධාවන (Middle Distance) ඉසව් ලෙස ජාත්‍යන්තරව පිළිගන්නා සම්මත ඉසව් දෙක මොනවාද?", "මීටර් 800 සහ මීටර් 1500", "මීටර් 100 සහ මීටර් 200", "මීටර් 5000 සහ මීටර් 10000", "මීටර් 400 සහ මීටර් 800", "මීටර් 800 සහ 1500 සවායු හා නිර්වායු ශක්ති පද්ධති දෙකෙහිම සංකලනයක් අවශ්‍ය වන මධ්‍යම දුර ඉසව් වේ."),
        q("මධ්‍යම සහ දිගු දුර ධාවන ඉසව් ආරම්භ කිරීම සඳහා ආරම්භක විනිසුරු විසින් ලබාදෙන විධානය කුමක්ද?", "'ඔබගේ ස්ථාන කරා' (On your marks) විධානය සහ අනතුරුව වෙඩි හඬ පමණි", "'සූදානම්' විධානය පමණි", "විධාන තුනම ලබාදේ", "'දුවන්න' කියා කෑගැසීම", "සිටගෙන ආරම්භ කරන ඉසව්වලට 'සූදානම්' (Set) විධානයක් නොමැති අතර 'ඔබගේ ස්ථාන කරා' කී පසු සන්සුන් වූ වහාම වෙඩි තබයි."),
        q("මීටර් 800 ධාවන ඉසව්වේදී ක්‍රීඩකයන් තමන්ගේම මංතීරුවල දිව ගොස් ඇතුළත පළමු මංතීරුවට කැපී යාමට (Breakline) අවසර ලැබෙන්නේ කවදාද?", "පළමු වක්‍රය (මීටර් 100 පමණ) අවසානයේ ඇති බිඳීමේ රේඛාව පසු කළ පසු", "ආරම්භ කළ සැනින්ම", "පළමු වටය අවසන් වූ පසු", "අවසාන මීටර් 100 දී පමණි", "මීටර් 800 ඉසව්වේ පළමු මීටර් 100 තමන්ගේ මංතීරුවේ දිව යා යුතු අතර බිඳීමේ රේඛාවෙන් පසු ඕනෑම මංතීරුවකට මාරු විය හැක."),
        q("මලල ක්‍රීඩාවේ දිගු දුර ධාවන (Long Distance) ඉසව් සඳහා අයත් වන ප්‍රධාන ධාවන පථ ඉසව් මොනවාද?", "මීටර් 5000 සහ මීටර් 10000", "මීටර් 800 සහ මීටර් 1500", "මීටර් 400 සහ මීටර් 800", "මීටර් 200 සහ මීටර් 400", "මීටර් 5000 (වට 12.5) සහ මීටර් 10000 (වට 25) ධාවන පථයේ පවත්වන දීර්ඝතම ඉසව් වේ."),
        q("සම්මත නිල මැරතන් (Marathon) ධාවන ඉසව්වක නිල දුර ප්‍රමාණය කිලෝමීටර් කීයද?", "කිලෝමීටර් 42.195කි (සැතපුම් 26යි යාර 385)", "කිලෝමීටර් 40.000කි", "කිලෝමීටර් 50.000කි", "කිලෝමීටර් 21.097කි", "මැරතන් ධාවනය මාර්ග ධාවන (Road race) ඉසව්වක් වන අතර එහි නිල දුර කිලෝමීටර් 42.195කි."),
        q("අර්ධ මැරතන් (Half Marathon) ඉසව්වක සම්මත දුර ප්‍රමාණය කොපමණද?", "කිලෝමීටර් 21.0975කි", "කිලෝමීටර් 20.000කි", "කිලෝමීටර් 10.000කි", "කිලෝමීටර් 25.000කි", "මැරතන් දුරින් හරියටම අඩක් වන කිලෝමීටර් 21.0975ක දුරක් අර්ධ මැරතන් සඳහා නියමිතය."),
        q("මලල ක්‍රීඩාවේ සම්මත සහය දිවීමේ (Relay) ප්‍රධාන ධාවන පථ ඉසව් දෙක මොනවාද?", "මීටර් 4 × 100 සහ මීටර් 4 × 400 සහය දිවීම්", "මීටර් 4 × 200 සහ මීටර් 4 × 800", "මීටර් 2 × 100 සහ මීටර් 2 × 400", "මීටර් 4 × 50 පමණි", "මෙම ඉසව් දෙකෙහිම එක් කණ්ඩායමකට ක්‍රීඩකයන් සිව්දෙනෙකු බැගින් සහභාගී වේ."),
        q("සහය දිවීමේදී භාවිත කරන යෂ්ටියේ (Baton) සම්මත දිග ප්‍රමාණය කොපමණද?", "සෙන්ටිමීටර 28 සිට 30 දක්වා", "සෙන්ටිමීටර 50 සිට 60 දක්වා", "සෙන්ටිමීටර 10 සිට 15 දක්වා", "මීටර් 1ක්", "යෂ්ටිය සිනිඳු මතුපිටක් සහිත හිස් ලෝහ හෝ ලී නළයක් වන අතර දිග 28-30cm විය යුතුය."),
        q("සහය දිවීමේ යෂ්ටියක (Baton) තිබිය යුතු අවම බර ප්‍රමාණය ග්‍රෑම් කීයද?", "අවම බර ග්‍රෑම් 50කි", "අවම බර ග්‍රෑම් 200කි", "අවම බර ග්‍රෑම් 100කි", "අවම බර ග්‍රෑම් 20කි", "යෂ්ටියේ බර අවම වශයෙන් ග්‍රෑම් 50ක් විය යුතු අතර පරිධිය සෙන්ටිමීටර 12-13ක් විය යුතුය."),
        q("ලෝක මලල ක්‍රීඩා සංගමයේ වත්මන් නව නීති අනුව මීටර් 4 × 100 සහය දිවීමේ 'යෂ්ටි හුවමාරු කලාපයේ' (Takeover Zone) මුළු දිග මීටර් කීයද?", "මීටර් 30ක තනි කලාපයකි", "මීටර් 20කි", "මීටර් 10කි", "මීටර් 40කි", "පැරණි නීතියේ තිබූ මීටර් 10 ත්වරණ කලාපය සහ මීටර් 20 හුවමාරු කලාපය ඒකාබද්ධ කර දැන් මීටර් 30ක තනි හුවමාරු කලාපයක් ඇත."),
        q("මීටර් 4 × 100 සහය දිවීමේදී යෂ්ටිය ලබාගන්නා ක්‍රීඩකයා ආපසු හැරී නොබලා උපරිම වේගයෙන් ඉදිරියට දුවමින් යෂ්ටිය ලබාගන්නා ක්‍රමය කුමක්ද?", "නොබලා හුවමාරුව (Non-visual Exchange)", "බලා හුවමාරුව", "ස්ථාවර හුවමාරුව", "විසි කිරීමේ හුවමාරුව", "වේගය අඩාල නොවී තබාගැනීම සඳහා සංඥා හඬකට අනුව නොබලා අත පසුපසට දිගු කර යෂ්ටිය ලබාගනී."),
        q("මීටර් 4 × 400 සහය දිවීමේදී ක්‍රීඩකයන් අතර යෂ්ටිය හුවමාරු කරගන්නා සම්මත ක්‍රමය කුමක්ද?", "බලා හුවමාරුව (Visual Exchange)", "නොබලා හුවමාරුව", "විසි කර දීම", "පිටුපසින් තල්ලු කිරීම", "ක්‍රීඩකයන් දැඩි තෙහෙට්ටුවට පත්ව සිටින බැවින් සහ මංතීරු අවුල් වන බැවින් බලා ආරක්ෂිතව යෂ්ටිය ලබාගනී."),
        q("යෂ්ටිය ලබාදීමේදී (Baton Exchange) පහළ සිට ඉහළට අත දිගු කර ලබාදෙන ක්‍රමය කුමක්ද?", "යටින් උඩට යෂ්ටිය දීමේ ක්‍රමය (Upsweep Technique)", "උඩින් යටට දීමේ ක්‍රමය", "තල්ලු කිරීමේ ක්‍රමය", "කරකවා දීමේ ක්‍රමය", "Upsweep ක්‍රමයේදී යෂ්ටිය ලබන්නාගේ පහළට යොමු වූ අත්ලට පහළ සිට ඉහළට තල්ලු කර ලබාදෙයි."),
        q("යෂ්ටිය ලබාදීමේදී ඉහළ සිට පහළට ලබන්නාගේ උඩුකුරු කළ අත්ල මත තබන ක්‍රමය කුමක්ද?", "උඩින් යටට යෂ්ටිය දීමේ ක්‍රමය (Downsweep Technique)", "යටින් උඩට දීමේ ක්‍රමය", "පැත්තෙන් දීමේ ක්‍රමය", "පසුපසින් දීමේ ක්‍රමය", "Downsweep ක්‍රමයේදී ලබන්නා අත්ල ඉහළට හරවා මාපටැඟිල්ල විහිදා තබන විට ඉහළ සිට යෂ්ටිය පහත් කරයි."),
        q("සහය දිවීමේ තරගයකදී යෂ්ටිය අතින් ගිලිහී බිම වැටුණහොත් ක්‍රියා කළ යුතු නිවැරදි නීත්‍යානුකූල ආකාරය කුමක්ද?", "යෂ්ටිය අතහැරුණු ක්‍රීඩකයා විසින්ම එය අහුලාගෙන අන් අයට බාධා නොවන සේ දිවීම ඉදිරියට ගෙන යා යුතුය", "ලබාගන්නා ක්‍රීඩකයා එය අහුලාගත යුතුය", "විනිසුරු විසින් එය අහුලා දිය යුතුය", "කණ්ඩායම වහාම තරගයෙන් ඉවත් වේ", "යෂ්ටිය බිම දැමූ ක්‍රීඩකයාම තම මංතීරුව තුළින් අහුලාගෙන අන් අයට බාධා නොකර ඉදිරියට දිව යාම නීත්‍යානුකූල වේ."),
        q("පිරිමි මීටර් 110 සහ කාන්තා මීටර් 100 කඩුලු පැනීමේ (Hurdles) ඉසව්වකදී එක් මංතීරුවකට යොදන සම්මත කඩුලු සංඛ්‍යාව කීයද?", "කඩුලු 10කි", "කඩුලු 8කි", "කඩුලු 12කි", "කඩුලු 5කි", "සියලුම සම්මත කඩුලු පැනීමේ ඉසව්වල (100m, 110m, 400m) එක් මංතීරුවක කඩුලු 10 බැගින් පිහිටයි."),
        q("පිරිමි මීටර් 110 කඩුලු පැනීමේ ඉසව්වේ කඩුල්ලක සම්මත උස ප්‍රමාණය කොපමණද?", "මීටර් 1.067කි (අඟල් 42)", "මීටර් 0.838කි", "මීටර් 0.914කි", "මීටර් 1.200කි", "පිරිමි 110m කඩුලු උසම කඩුලු ඉසව්ව වන අතර එහි උස මීටර් 1.067කි."),
        q("කාන්තා මීටර් 100 කඩුලු පැනීමේ ඉසව්වේ කඩුල්ලක සම්මත උස ප්‍රමාණය කීයද?", "මීටර් 0.838කි (අඟල් 33)", "මීටර් 1.067කි", "මීටර් 0.762කි", "මීටර් 0.914කි", "කාන්තා 100m කඩුලු ඉසව්වේ කඩුල්ලක උස මීටර් 0.838කි."),
        q("කඩුලු පැනීමේදී කඩුල්ල මතින් මුලින්ම ඉදිරියට දිගු කරන පාදය හඳුන්වන්නේ කෙසේද?", "පෙර පාදය හෙවත් නායක පාදය (Lead Leg)", "පසු පාදය (Trail Leg)", "පිටත්වීමේ පාදය", "ආධාරක පාදය", "Lead leg මගින් ශරීරය ඉදිරියට ඇදගන්නා අතර කඩුල්ලට ඉහළින් කෙළින්ම දිගු වේ."),
        q("කඩුලු පැනීමේදී පෙර පාදයට පිටුපසින් කඩුල්ලට සමාන්තරව නවාගෙන එන පාදය හඳුන්වන්නේ කෙසේද?", "පසු පාදය (Trail Leg)", "පෙර පාදය", "පැනීමේ පාදය", "ස්ථාවර පාදය", "Trail leg දණහිස පිටතට නවා කඩුල්ලට ඉහළින් ඉක්මනින් ඉදිරියට ගෙන එයි."),
        q("කඩුලු පැනීමේ තරගයකදී ධාවකයෙකුගේ පාදය වැදී කඩුල්ලක් බිම පෙරළුණහොත් සිදුවන්නේ කුමක්ද?", "එය හිතාමතා අතින් තල්ලු නොකළේ නම් කිසිදු වරදක් නොවන අතර දිවීම වලංගු වේ", "ක්‍රීඩකයා වහාම තරගයෙන් ඉවත් කෙරේ", "තත්පර 5ක දඬුවම් කාලයක් එකතු වේ", "තරගය නැවත ආරම්භ කෙරේ", "නොදැනුවත්ව කඩුල්ල පෙරළීම වරදක් නොවන නමුත් හිතාමතා කඩුල්ල අතින් තල්ලු කර පෙරළීම නුසුදුසුකමකි."),
        q("උස පැනීමේ (High Jump) ඉසව්වේදී වර්තමානයේ ලොව වඩාත්ම ජනප්‍රිය සහ කාර්යක්ෂම ශිල්පීය ක්‍රමය කුමක්ද?", "ෆොස්බරි ෆ්ලොප් ක්‍රමය (Fosbury Flop)", "කතුරුවැටි ක්‍රමය (Scissors)", "ස්ට්‍රැඩ්ල් ක්‍රමය (Straddle)", "නැගෙනහිර කපාහැරීම", "ඩික් ෆොස්බරි විසින් හඳුන්වා දුන් ෆ්ලොප් ක්‍රමයේදී උඩුකුරුව තීරුවට පිටුපස හරවා පැන උරහිස් මතින් මෙට්ටයට ගොඩබසී."),
        q("ෆොස්බරි ෆ්ලොප් (Fosbury Flop) උස පැනීමේ ක්‍රමයේ ධාවන ප්‍රවේශයේ (Approach Run) හැඩය කුමක්ද?", "'J' අකුරක හැඩැති වක්‍ර ධාවනයකි", "සෘජුකෝණාස්‍රාකාර ධාවනයකි", "කෙළින්ම ඉදිරියට දිවීමකි", "'S' හැඩැති ධාවනයකි", "මුලින් කෙළින් දිව විත් අවසාන පියවර 4-5 කවයක චාපයක් මෙන් වක්‍රව දිව ඒමෙන් කේන්ද්‍රාභිසාරී බලය උපදී."),
        q("උස පැනීමේදී පිම්ම සඳහා පිටත්වීම (Take-off) සිදුකළ යුතු ආකාරය පිළිබඳ අනිවාර්ය නීතිය කුමක්ද?", "තනි පාදයකින් පමණක් පිටත්වීම සිදුකළ යුතුය", "දෙපයින් එකවර පැනිය හැක", "අත් ආධාරයෙන් පැනිය හැක", "කැමති ඕනෑම ආකාරයකට පැනිය හැක", "World Athletics නීතිය අනුව උස පැනීමේදී දෙපයින් එකවර පිටත්වීම නීති විරෝධී වන අතර තනි පාදයකින් පමණක් පැනිය යුතුය."),
        q("උස පැනීමේදී ක්‍රීඩකයෙකුට එක් උසකදී ලබාදෙන උපරිම අසාර්ථක උත්සාහයන් (Trials) ගණන කීයද?", "අඛණ්ඩව අසාර්ථක උත්සාහයන් 3ක්", "අසාර්ථක උත්සාහයන් 2ක්", "එක් උත්සාහයක් පමණි", "අසීමිත උත්සාහයන් ගණනක්", "ඕනෑම එක් උසකදී හෝ අනුක්‍රමික උසවල්වලදී පිට පිට 3 වතාවක් අසාර්ථක වුවහොත් තරගයෙන් ඉවත් වේ."),
        q("දුර පැනීමේ (Long Jump) ඉසව්වේදී වාතයේ පියාසර කිරීමේ ශිල්පීය ක්‍රම තුන නිවැරදිව දැක්වෙන්නේ කුමන පිළිතුරේද?", "රුවල් ක්‍රමය (Sail), එල්ලෙන ක්‍රමය (Hang) සහ වාතයේ පියවර තැබීම (Hitch-kick)", "ෆ්ලොප්, කතුරුවැටිය සහ ස්ට්‍රැඩ්ල්", "ලිස්සා යාම, කරකැවීම සහ විසි කිරීම", "හොප්, ස්ටෙප් සහ ජම්ප්", "Sail, Hang සහ Hitch-kick යනු දුර පැනීමේ ප්‍රධාන පියාසර (Flight) ශිල්පීය ක්‍රම තුනයි."),
        q("දුර පැනීමේදී පිටත්වීමේ පුවරුවෙන් (Take-off Board) පසුපසින් ඇති වැරදි පිමි සලකුණු කරන ද්‍රව්‍යය කුමක්ද?", "ප්ලාස්ටිසීන් දර්ශක පුවරුව (Plasticine Indicator Board)", "හුණු කුඩු", "වැලි තට්ටුව", "ලී ලෑල්ල", "ක්‍රීඩකයාගේ සපත්තුව ප්ලාස්ටිසීන් මත වැදී සලකුණක් තැබුවහොත් එය අසාර්ථක වැරදි පිම්මක් (Foul jump) ලෙස සටහන් වේ."),
        q("දුර පැනීමේ පිම්මක දුර මනිනු ලබන්නේ කෙසේද?", "පිටත්වීමේ පුවරුවේ දාරයේ සිට වැලි වල තුළ ශරීරයේ ඕනෑම කොටසක් ස්පර්ශ වූ ආසන්නතම ලක්ෂ්‍යයට සෘජුකෝණීව", "වැලි වලේ මැදට", "පිටත්වූ ස්ථානයේ සිට ඈතම ලක්ෂ්‍යයට", "ක්‍රීඩකයා නැගී සිටි ස්ථානයට", "ශරීරය, අත හෝ ඇඳුම වැලි මත තැබූ පිටත්වීමේ රේඛාවට ළඟම සලකුණේ සිට පුවරුවේ ඉදිරිපස දාරයට මනිනු ලැබේ."),
        q("තුන්පිම්ම (Triple Jump) ඉසව්වේ අදියර ත්‍රිත්වය නිවැරදි අනුපිළිවෙළින් දැක්වෙන පිළිතුර කුමක්ද?", "හොප් — ස්ටෙප් — ජම්ප් (Hop, Step, Jump)", "ජම්ප් — හොප් — ස්ටෙප්", "ස්ටෙප් — ජම්ප් — හොප්", "හොප් — ජම්ප් — ස්ටෙප්", "තුන්පිම්මේ අනුපිළිවෙළ Hop (පිටත්වූ පාදයෙන්ම ගොඩබැසීම), Step (අනෙක් පාදයෙන් ගොඩබැසීම) සහ Jump (වැලි වලට පැනීම) වේ."),
        q("තුන්පිම්මේ පළමු පිම්ම වන 'හොප්' (Hop) අදියරේදී ගොඩබැසිය යුතු නිවැරදි ආකාරය කුමක්ද?", "පිටත්වීමේ පුවරුවෙන් පිටත් වූ පාදයෙන්ම නැවත ගොඩබැසීම", "අනෙක් පාදයෙන් ගොඩබැසීම", "දෙපයින් එකවර ගොඩබැසීම", "දණහිස බිම තැබීම", "හොප් අදියරේදී පිටත්වූ පාදයෙන්ම ගොඩබසින අතර ස්ටෙප් අදියරේදී අනෙක් පාදයට මාරු වේ."),
        q("තුන්පිම්මේ 'ස්ටෙප්' (Step) අදියරේදී සිදුවන පාද මාරුව කුමක්ද?", "හොප් ගොඩබැසූ පාදයෙන් පිටත්ව විරුද්ධ පාදයෙන් ගොඩබැසීම", "එම පාදයෙන්ම නැවත ගොඩබැසීම", "දෙපා එකතු කර ගොඩබැසීම", "අත් බිම තැබීම", "ස්ටෙප් අදියරේදී පාදය මාරු වී ප්‍රබල පියවරක් ඉදිරියට තබයි."),
        q("යගුලිය දැමීමේ (Shot Put) ඉසව්වේදී යගුලිය විසි කරන කවාකාර සීමාවේ (Throwing Circle) සම්මත විෂ්කම්භය කීයද?", "මීටර් 2.135කි (අඩි 7)", "මීටර් 2.500කි", "මීටර් 1.500කි", "මීටර් 3.000කි", "යගුලිය දැමීමේ සහ මිටිය විසිකිරීමේ කවයේ විෂ්කම්භය මීටර් 2.135ක් වේ."),
        q("යගුලිය දැමීමේ කවයේ ඉදිරිපස සවිකර ඇති ලීයෙන් සාදන ලද ආධාරකය හඳුන්වන්නේ කෙසේද?", "නවත්වන පුවරුව හෙවත් නැවතුම් බාධකය (Stop Board / Toe Board)", "පිටත්වීමේ පුවරුව", "කඩුල්ල", "සීමා මායිම", "Stop board හි දිග මීටර් 1.21-1.23 ක් සහ උස සෙන්ටිමීටර 10ක් වන අතර එය මත හෝ ඉන් පිටත පය නොතැබිය යුතුය."),
        q("ජ්‍යෙෂ්ඨ පිරිමි යගුලිය දැමීමේ ඉසව්වේ සම්මත යගුලියේ නිල බර ප්‍රමාණය කොපමණද?", "කිලෝග්‍රෑම් 7.26කි (රාත්තල් 16)", "කිලෝග්‍රෑම් 5.00කි", "කිලෝග්‍රෑම් 4.00කි", "කිලෝග්‍රෑම් 6.00කි", "ඔලිම්පික් හා ජාත්‍යන්තර පිරිමි යගුලියේ නිල බර කිලෝග්‍රෑම් 7.26ක් (7.260 kg) වේ."),
        q("ජ්‍යෙෂ්ඨ කාන්තා යගුලිය දැමීමේ ඉසව්වේ සම්මත යගුලියේ නිල බර ප්‍රමාණය කීයද?", "කිලෝග්‍රෑම් 4.00කි", "කිලෝග්‍රෑම් 5.00කි", "කිලෝග්‍රෑම් 3.00කි", "කිලෝග්‍රෑම් 7.26කි", "කාන්තා ජ්‍යෙෂ්ඨ යගුලියේ බර කිලෝග්‍රෑම් 4.00ක් (4.000 kg) වේ."),
        q("යගුලිය දැමීමේදී යගුලිය මුදාහැරිය යුතු නිවැරදි කායික ක්‍රමවේදය කුමක්ද?", "නිකට හෝ බෙල්ල අසල තද කර තබා එක් අතකින් ඉදිරියට තල්ලු කිරීම (Pushed)", "පන්දුවක් මෙන් අත පිටුපසට කරකවා විසිකිරීම", "දෑතින්ම අල්ලා විසි කිරීම", "යටින් උඩට දැමීම", "යගුලිය උරහිස් රේඛාවෙන් පිටුපසට නොගෙන බෙල්ල අසල සිට එක් අතකින් ඉදිරියට තල්ලු කළ යුතුය."),
        q("යගුලිය, කවපෙත්ත සහ මිටිය පතිත විය යුතු සම්මත ගොඩබෑමේ අංශක කලාපය (Landing Sector) කොපමණද?", "අංශක 34.92ක කෝණික කලාපයකි", "අංශක 45ක කලාපයකි", "අංශක 60ක කලාපයකි", "අංශක 90ක කලාපයකි", "විසිකිරීමේ කවයේ කේන්ද්‍රයේ සිට අංශක 34.92ක කෝණයකින් විහිදෙන සීමා රේඛා තුළට අවිය පතිත විය යුතුය."),
        q("විසිකිරීමේ ඉසව්වකදී (යගුලිය, කවපෙත්ත) ක්‍රීඩකයා තම විසිකිරීම අවසන් කර කවයෙන් පිටවිය යුතු නිවැරදි ආකාරය කුමක්ද?", "අවිය බිම පතිත වූ පසු කවයේ මැද සලකුණු කළ සුදු රේඛාවට පිටුපස අර්ධයෙන් පාලනය සහිතව පිටවීම", "ඉදිරිපසින් පැන පිටවීම", "අවිය අහසේ තිබියදීම පිටවීම", "කැමති ඕනෑම පැත්තකින් දිව යාම", "ඉදිරිපසින් පිටවීම හෝ අවිය බිම වැටීමට පෙර පිටවීම පිම්ම නිෂ්ප්‍රභ වීමට (Foul) හේතුවේ."),
